    component_sizes = []

    def dfs(u):
        count = 0
        stack = [u]
        visited[u] = True
        while stack:
            node = stack.pop()
            count += 1
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
        return count

    for i in range(1, n + 1):
        if not visited[i]:
            size = dfs(i)
            component_sizes.append(size)

    # Find connected components
    for i in range(1, n + 1):
        if not visited[i]:
            size = dfs(i)
            component_sizes.append(size)

    if not component_sizes:
        return '-1\n'

    # Generate lucky numbers up to n
    lucky_numbers = set()
    def generate_lucky(current, length):
        if current > n:
            return
        if current > 0 and current <= n:
            lucky_numbers.add(current)
        if length == 3:
            return
        generate_lucky(current * 10 + 4, length + 1)
        generate_lucky(current * 10 + 7, length + 1)

    generate_lucky(0, 0)
    lucky_numbers.discard(0)

    # Check if any component size is already a lucky number
    for size in component_sizes:
        if size in lucky_numbers:
            return '0\n'

    # Sort components for better DP efficiency
    component_sizes.sort(reverse=True)

    # DP: dp[s] = minimum number of components to get sum s
    min_components = {}
    for size in component_sizes:
        new_sums = set()
        for s in min_components:
            if s + size in lucky_numbers:
                count = min_components[s] + 1
                if count < min_components.get(s + size, float('inf')):
                    min_components[s + size] = count
        if size in lucky_numbers:
            min_components[size] = 1

    # Collect all achievable sums
    for i in range(1, n + 1):
        if i in lucky_numbers and min_components.get(i) is not None:
            ans = min_components[i] - 1  # roads = components - 1
            return f'{ans}\n'

    return '-1\n'

