class Solution:
    def solve_geometric(self, n, competitors):
        if n == 0:
            return []

        # Sort by swimming speed, then by running speed descending
        # This creates an ordering where we can eliminate non-optimizable competitors
        sorted_comps = sorted(range(n), key=lambda x: (-competitors[x][0], -competitors[x][1]))

        winners = set()
        minima = []  # store pairs of (swimming_speed, running_speed) that are not dominated

        for idx in sorted_comps:
            si, ri = competitors[idx]
            dominated = False

            for prev_s, prev_r in minima:
                if si <= prev_s and ri <= prev_r:
                    # Current is dominated by someone with better or equal swimming and running
                    if (si == prev_s and ri == prev_r):
                        # Exactly equal - they're also dominated (can't be strictly faster)
                        dominated = True
                    break

            if not dominated:
                # Check if there's ANY pair in minima that strictly dominates old
                dominated = False
                for prev_s, prev_r in minima:
                    if si >= prev_s * 2 and ri >= prev_r * 2:
                        dominated = True
                        break

                if not dominated:
                    minima.append((si, ri))

        return sorted_comps if minima else []


