        speeds.append(parts)

    # For each person, check if they could win
    winners = []

    for i in range(n):
        si, ri = speeds[i]
        could_win = True

        for j in range(n):
            if i == j:
                continue

            sj, rj = speeds[j]

            # If person j has better or equal swimming AND better or equal running
            # then person i can never be strictly faster
            if sj >= si and rj >= ri:
                if sj == si and rj == ri:
                    continue  # Same speeds - technically they finish at same time, not strictly winning
                could_win = False
                break

        if could_win:
            winners.append(i + 1)

    # Return as space-separated string
    return ' '.join(map(str, winners)) + ' \n'


