    # Tarjan's algorithm for SCCs
    ids = [-1] * (n + 1)
    low = [-1] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    scc_id = [-1] * (n + 1)
    scc_count = [0]

    def dfs1(u):
        ids[u] = low[u] = scc_count[0]
        scc_count[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if ids[v] == -1:
                dfs1(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = ids[u]
                if u == v:
                    break

