        if ids[i] == -1:
            dfs1(i)

    # For each SCC, find the GCD of all cycle lengths
    scc_gcd = [0] * (n + 1)

    for root in range(1, n + 1):
        sc_id = scc_id[root]
        if sc_id == -1 or scc_gcd[sc_id] > 0:
            continue

        # BFS to find distances from root within this SCC
        dist = {}
        queue = [root]
        dist[root] = 0

        while queue:
            u = queue.pop(0)
            for v, w in adj[u]:
                if scc_id[v] != sc_id:
                    continue
                if v not in dist:
                    dist[v] = dist[u] + w
                    queue.append(v)

        # Find back edges and compute cycle lengths
        for u in dist:
            for v, w in adj[u]:
                if scc_id[v] != sc_id:
                    continue
                if v in dist:
                    length = dist[u] + w - dist[v]
                    scc_gcd[sc_id] = math.gcd(scc_gcd[sc_id], length)

