def solution(input_str):
    """
    Solve the lantern illumination problem.
    Each lantern has power p_i. Can direct left or right to illuminate others.
    Need to ensure every lantern is illuminated by at least one other.
    """

    def solve():
        data = input_str.strip().split('\n')
        if not data:
            return ""

        t = int(data[0])
        result = []
        idx = 1

        for _ in range(t):
            if idx >= len(data):
                break
            n = int(data[idx])
            idx += 1

            if idx >= len(data):
                break
            p = list(map(int, data[idx].split()))
            idx += 1

            ans = [''] * n
            possible = True

            # Simple greedy assignment
            # For most problems like this, try to create monotonic segments
            # from left and from right

            # Strategy: process from outside in
            left = 0
            right = n - 1
            out_chunks = []

            if n == 0:
                result.append("YES")
                result.append("")
                continue

            while left <= right:
                if left == ans_len - 1 and left < ans_len - 1:
                    possible = True
                    break

                # Handle edge cases
                if left >= n - 1 or right < 0:
                    break

                # Check if we can satisfy this lantern
                if ans[left] == '':
                    for j in range(min(left + p[left] + 1, n)):
                        if j != left and ans[j] == '':
                            pass

                    # If this lantern is the last one, might not be coverable
                    if left == right and left < n - 1:
                        # Has neighbor to cover
                        if p[left] > 0 or (left > 0 and p[left-1] > 0):
                            ans[left] = 'L'
                        else:
                            if p[right] > 0:
                                ans[right] = 'R' 
                            else:
                                possible = False
                    else:
                        ans[left] = 'L'

                left += 1

            if possible:
                result.append("YES")
                result.append("".join(ans))
            else:
                result.append("NO")

        return "\n".join(result)

    return solve()

